package transport

import (
    "context"
    "errors"
    "google.golang.org/grpc/codes"
    "google.golang.org/grpc/status"
)

func MapError(err error) error {
    if err == nil { return nil }
    switch {
    case errors.Is(err, ErrInvalid): return status.Error(codes.InvalidArgument, "invalid request")
    case errors.Is(err, ErrNotFound): return status.Error(codes.NotFound, "not found")
    case errors.Is(err, ErrConflict): return status.Error(codes.AlreadyExists, "already exists")
    case errors.Is(err, context.DeadlineExceeded): return status.Error(codes.DeadlineExceeded, "deadline exceeded")
    case errors.Is(err, context.Canceled): return status.Error(codes.Canceled, "canceled")
    default: return status.Error(codes.Internal, "internal error")
    }
}
